    OrderUnit = apps.get_model('store', 'OrderUnit')
    StockMovement = apps.get_model('store', 'StockMovement')
    StockUnit = apps.get_model('store', 'StockUnit')

    waiting = set(
        Order.objects.filter(
            fulfillment_status__in=('pending', 'confirmed', 'preparing', 'ready_for_pickup'),
        ).values_list('pk', flat=True)
    )
    seen = set(OrderUnit.objects.values_list('order_id', 'unit_id'))

    def write(order_id, company_id, unit, when):
        if order_id in waiting:
            return
        if unit is None or unit.company_id != company_id or (order_id, unit.pk) in seen:
            return
        seen.add((order_id, unit.pk))
        OrderUnit.objects.create(
            company_id=company_id, order_id=order_id, product_id=unit.product_id, unit_id=unit.pk,
            method='legacy', identified_by=None, identified_at=when, left_at=when,       # history: it left
        )

    for movement in StockMovement.objects.filter(movement_type='sale_exit', order__isnull=False).order_by('pk').iterator():
        ids = [value for value in ((movement.metadata or {}).get('unit_ids') or []) if isinstance(value, int)]
        if not ids:
            continue
        units = {unit.pk: unit for unit in StockUnit.objects.filter(pk__in=ids)}
        for unit_id in ids:
            write(movement.order_id, movement.company_id, units.get(unit_id), movement.created_at)
    for unit in StockUnit.objects.filter(order__isnull=False).iterator():
        write(unit.order_id, unit.company_id, unit, unit.sold_at or unit.updated_at)


